INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 2, 1, "2024/10/31 12:00:00", 2.1, "2030/01/01 14:59:59", -416.5, 100, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 3001100, 3001, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 2, 4, "2024/10/31 12:00:00", 5.68, "2030/01/01 14:59:59", -416.5, 101, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 3001101, 3001, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 1, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 102, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 3001102, 3001, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 1, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 100, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 3002100, 3002, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 1, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 101, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 3002101, 3002, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 2, 5, "2024/10/31 12:00:00", 8.53, "2030/01/01 14:59:59", -416.5, 102, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 3002102, 3002, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 7, "2024/10/31 12:00:00", 5.67, "2030/01/01 14:59:59", -416.5, 103, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 3002103, 3002, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 1, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 104, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 3002104, 3002, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 3, 3, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 300, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3002300, 3004, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 7, 7, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 301, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 3002400, 3005, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 1, 2, "2024/10/31 12:00:00", 4.4, "2030/01/01 14:59:59", -416.5, 200, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 3003200, 3003, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 7, 7, "2024/10/31 12:00:00", 0, "2030/01/01 14:59:59", -416.5, 201, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 3003201, 3003, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (0, 2, 1, "2024/10/31 12:00:00", 5.6, "2030/01/01 14:59:59", -416.5, 202, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 3003202, 3003, "フブキ", 130211);
